import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"版本发布","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"版本发布 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/reference/releases"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/reference/releases"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/releases"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/releases"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/releases"}]]},"headers":[],"relativePath":"zh/xclang/reference/releases.md","filePath":"zh/xclang/reference/releases.md","lastUpdated":1794509097000}'),c={name:"zh/xclang/reference/releases.md"};function l(r,e,i,n,s,h){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="版本发布" tabindex="-1">版本发布 <a class="header-anchor" href="#版本发布" aria-label="Permalink to &quot;版本发布&quot;">​</a></h1><p>xclang 的每个版本都会发布到 GitHub Releases、clice conda 频道、CMake <code>FetchContent</code> 以及 clice Bazel registry。安装 xclang 的方式见<a href="./../guide/quick-start">快速开始</a>，解压后压缩包内的目录结构见<a href="./layout">压缩包目录结构</a>。</p><h2 id="版本号" tabindex="-1">版本号 <a class="header-anchor" href="#版本号" aria-label="Permalink to &quot;版本号&quot;">​</a></h2><p>每个版本的标签格式均为 <code>&lt;llvm version&gt;.&lt;revision&gt;</code>。例如 <code>23.1.2.1</code> 是基于 LLVM 23.1.2 的第一次构建，<code>23.1.2.2</code> 是第二次。版本号直接标明上游 LLVM 版本，并在 conda、Bazel 和 CMake 中保持一致的排序顺序。</p><p>已发布的版本不会覆盖替换。任何修复或重新构建都会作为下一个修订号发布，发布工作流也会拒绝已存在的版本标签。每个版本号及其压缩包的 <code>sha256</code> 摘要永久指向逐字节相同的内容。每个版本的变更记录在 <a href="https://github.com/clice-io/xclang/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a> 中。</p><h2 id="重新打包-repack" tabindex="-1">重新打包（Repack） <a class="header-anchor" href="#重新打包-repack" aria-label="Permalink to &quot;重新打包（Repack）&quot;">​</a></h2><p>当改动只涉及打包层（例如 Bazel 模块、CMake 包或目标平台配置文件）时，新版本会采用 <em>repack</em> 方式发布：下一个修订号直接复用上一版本的编译器与运行时库，二者逐字节相同。</p><h2 id="分发渠道" tabindex="-1">分发渠道 <a class="header-anchor" href="#分发渠道" aria-label="Permalink to &quot;分发渠道&quot;">​</a></h2><p>各个分发渠道都会以 <code>&lt;version&gt;</code> 发布版本，并支持锁定特定版本或获取最新版本：</p><table tabindex="0"><thead><tr><th>渠道</th><th>发布内容</th><th>锁定版本</th><th>获取最新版本</th></tr></thead><tbody><tr><td><a href="https://github.com/clice-io/xclang/releases" target="_blank" rel="noreferrer">GitHub Releases</a></td><td>全部 17 个发布文件</td><td><code>releases/download/&lt;version&gt;</code></td><td><code>releases/latest</code>，其中的 <code>SHA256SUMS</code> 标明了具体版本号</td></tr><tr><td><a href="https://conda.clice.io" target="_blank" rel="noreferrer">conda.clice.io</a></td><td>基于发布压缩包构建的各主机 <code>xclang</code> 包与 <code>noarch</code> 的 <code>llvm-option-inc</code> 包</td><td><code>xclang = &quot;&lt;version&gt;.*&quot;</code>（软件包构建号记录这个版本的打包修复次数）</td><td><code>xclang = &quot;*&quot;</code>，由 <code>pixi.lock</code> 锁定，直到运行 <code>pixi update</code></td></tr><tr><td>CMake FetchContent</td><td>仓库标签 <code>&lt;version&gt;</code></td><td><code>GIT_TAG &lt;version&gt;</code></td><td><code>GIT_TAG latest</code>（指向最新发布标签的分支）</td></tr><tr><td><a href="https://bazel.clice.io" target="_blank" rel="noreferrer">bazel.clice.io</a></td><td>基于发布压缩包构建并测试通过后发布的 <code>xclang</code> Bazel 模块</td><td><code>version = &quot;&lt;version&gt;&quot;</code></td><td>Bazel 自动解析依赖图中请求的最高版本</td></tr></tbody></table><h2 id="发布文件" tabindex="-1">发布文件 <a class="header-anchor" href="#发布文件" aria-label="Permalink to &quot;发布文件&quot;">​</a></h2><p>每个 <a href="https://github.com/clice-io/xclang/releases" target="_blank" rel="noreferrer">GitHub 版本</a>都包含固定的 17 个发布文件：</p><table tabindex="0"><thead><tr><th>发布文件</th><th>内容</th><th>大小</th></tr></thead><tbody><tr><td><code>xclang-&lt;version&gt;-&lt;host&gt;.tar.xz</code></td><td>工具链压缩包，每个主机平台一个，内置全部八个目标平台（<a href="./layout">压缩包目录结构</a>）</td><td>约 100 MB</td></tr><tr><td><code>libclang-&lt;version&gt;-&lt;host&gt;.tar.xz</code></td><td><code>clang</code> 与 LLVM 的静态库及头文件，每个主机平台一个（<a href="./../features/libclang">libclang</a>）</td><td>约 265 MB</td></tr><tr><td><code>libclang-&lt;version&gt;-&lt;host&gt;-asan.tar.xz</code></td><td>带 ASan 插桩的 <code>libclang</code> 构建，提供 Linux x64 与 macOS arm64 版本（<a href="./../features/libclang#the-asan-build">ASan 构建</a>）</td><td>约 200 MB</td></tr><tr><td><code>llvm-option-inc-&lt;version&gt;.tar.xz</code></td><td>预先生成的 <code>clang</code>、<code>lld</code>、<code>llvm-lib</code> 与 <code>llvm-dlltool</code> 选项表（<a href="./../features/libclang#the-option-tables">选项表</a>）</td><td>约 200 KB</td></tr><tr><td><code>xclang-&lt;version&gt;.profdata</code></td><td>构建这个版本所用的 PGO profile（<a href="./../design/pgo">PGO</a>）</td><td>约 50 MB</td></tr><tr><td><code>SHA256SUMS</code></td><td>这个版本中其余所有发布文件的 <code>sha256</code> 摘要</td><td></td></tr></tbody></table><p>六个 <code>&lt;host&gt;</code> triple 分别为 <code>x86_64-unknown-linux-gnu</code>、<code>aarch64-unknown-linux-gnu</code>、<code>x86_64-w64-mingw32</code>、<code>aarch64-w64-mingw32</code>、<code>aarch64-apple-darwin</code> 和 <code>x86_64-apple-darwin</code>。</p><h2 id="校验下载文件" tabindex="-1">校验下载文件 <a class="header-anchor" href="#校验下载文件" aria-label="Permalink to &quot;校验下载文件&quot;">​</a></h2><p>发布工作流会根据上传的发布文件生成 <code>SHA256SUMS</code>。你可以对照 <code>SHA256SUMS</code> 校验任意下载的发布文件（如需指定版本，向 <code>gh release download</code> 传入 <code>&lt;version&gt;</code>）：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clice-io/xclang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;llvm-option-inc-*&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-missing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span></span></code></pre></div><p>Bazel 模块会对照 <code>versions.bzl</code> 中锁定的 <code>sha256</code> 摘要校验每个下载的压缩包；CMake 的 <code>xclang.cmake</code> 则会对照这个版本的 <code>SHA256SUMS</code> 文件校验工具链压缩包。在 <code>versions.bzl</code> 或你自己的仓库中锁定摘要，还能防范 GitHub 上的压缩包与 <code>SHA256SUMS</code> 被同时替换（<a href="./../design/roadmap#immutable-releases">不可变 GitHub 版本</a>）。</p><h2 id="可复现构建" tabindex="-1">可复现构建 <a class="header-anchor" href="#可复现构建" aria-label="Permalink to &quot;可复现构建&quot;">​</a></h2><p>每次发布都会在两台机器上各打包一次每个主机的压缩包、各构建一次 <code>xclang</code> 命令，再逐字节比对：压缩包里的条目按顺序排列，时间取提交的时间，不记录所有者，并按固定分块压缩。用某个修订号的 profile（<code>xclang-&lt;version&gt;.profdata</code>）重新构建，应当能得到完全相同的全部压缩包；每次完整重建都会再启动一次完整构建，在发布之前确认这一点。这是检查出来的，不是保证：构建 xclang 的编译器或链接器本身有 bug，就可能破坏它。重新构建还需要 GitHub 的 runner，因为程序里留有构建时的部分路径，macOS 构建也会记下 runner 上 Xcode 的 SDK 版本。</p>`,20)])])}const k=t(c,[["render",l]]);export{g as __pageData,k as default};
